{
  "hooks": {
    "PreToolUse": [
      {
        "matcher": "Bash",
        "hooks": [
          {
            "type": "command",
            "if": "Bash(npm install *)",
            "command": "jq -n '{hookSpecificOutput: {hookEventName: \"PreToolUse\", permissionDecision: \"ask\", permissionDecisionReason: \"New packages change your project. Confirm to continue.\"}}'"
          }
        ]
      }
    ]
  }
}

{
  "hooks": {
    "PreToolUse": [
      {
        "matcher": "Bash",
        "hooks": [
          {
            "type": "command",
            "if": "Bash(pip install *)",
            "command": "jq -n '{hookSpecificOutput: {hookEventName: \"PreToolUse\", permissionDecision: \"ask\", permissionDecisionReason: \"Check you are in a virtual environment, then confirm.\"}}'"
          }
        ]
      }
    ]
  }
}

{
  "hooks": {
    "PreToolUse": [
      {
        "matcher": "Bash",
        "hooks": [
          {
            "type": "command",
            "if": "Bash(git commit *)",
            "command": "jq -n '{hookSpecificOutput: {hookEventName: \"PreToolUse\", permissionDecision: \"ask\", permissionDecisionReason: \"Review the staged changes and message, then confirm.\"}}'"
          }
        ]
      }
    ]
  }
}

#!/bin/bash
FILE=$(jq -r '.tool_input.file_path // empty')
case "$FILE" in
  *.py)
    OUT=$(ruff check "$FILE" 2>&1) || { echo "$OUT" >&2; exit 2; }
    ;;
esac
exit 0

#!/bin/bash
FILE=$(jq -r '.tool_input.file_path // empty')
case "$FILE" in
  *.sh)
    OUT=$(shellcheck "$FILE" 2>&1) || { echo "$OUT" >&2; exit 2; }
    ;;
esac
exit 0

#!/bin/bash
FILE=$(jq -r '.tool_input.file_path // empty')
case "$FILE" in
  *.py)
    OUT=$(python3 -m py_compile "$FILE" 2>&1) || { echo "$OUT" >&2; exit 2; }
    ;;
esac
exit 0

#!/bin/bash
FILE=$(jq -r '.tool_input.file_path // empty')
case "$FILE" in
  *.json)
    OUT=$(jq empty "$FILE" 2>&1) || { echo "Invalid JSON in $FILE: $OUT" >&2; exit 2; }
    ;;
esac
exit 0

{
  "hooks": {
    "PostToolUse": [
      {
        "matcher": "Edit|Write",
        "hooks": [
          {
            "type": "command",
            "command": "jq -r '.tool_input.file_path // empty' | grep -E '\\.md$' | xargs -r npx prettier --write --prose-wrap preserve"
          }
        ]
      }
    ]
  }
}

#!/bin/bash
FILE=$(jq -r '.tool_input.file_path // empty')
case "$FILE" in
  *.py)
    OUT=$(pytest -x -q 2>&1) || { echo "$OUT" | tail -n 25 >&2; exit 2; }
    ;;
esac
exit 0

{
  "hooks": {
    "UserPromptSubmit": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "echo 'Reminder: separate what you know from what should be verified, and name any source you rely on.'"
          }
        ]
      }
    ]
  }
}

{
  "hooks": {
    "UserPromptSubmit": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "echo 'Study mode: give a hint or a guiding question first. Share a full solution only if the user asks twice.'"
          }
        ]
      }
    ]
  }
}

#!/bin/bash
case "$(date +%u)" in
  1|3) echo "Today is a practice day: prefer exercises over lectures." ;;
  2|4) echo "Today is a reading day: summarize and explain concepts." ;;
  5) echo "Today is a review day: quiz the user on the week." ;;
  *) echo "Weekend: keep sessions short and light." ;;
esac
